+export function nextIndex(current: number, count: number, key: string): number {
+  if (count === 0) return -1;
+  if (key === 'Home') return 0;
+  if (key === 'End') return count - 1;
+  if (key === 'ArrowDown') return Math.min(current + 1, count - 1);
+  if (key === 'ArrowUp') return Math.max(current - 1, 0);
+  return current;
+}
+
+export function wireKeyboard(list: HTMLElement): void {
+  list.addEventListener('keydown', (event) => {
+    const rows = [...list.querySelectorAll<HTMLElement>('.row')];
+    const current = rows.indexOf(document.activeElement as HTMLElement);
+    const next = nextIndex(current, rows.length, event.key);
+    if (next >= 0 && next !== current) {
+      event.preventDefault();
+      rows[next]?.focus();
+    }
+  });
+}
