+import { expect, test } from 'bun:test';
+import { nextIndex } from './keyboard';
+
+test('moves down and clamps at the last row', () => {
+  expect(nextIndex(0, 3, 'ArrowDown')).toBe(1);
+  expect(nextIndex(2, 3, 'ArrowDown')).toBe(2);
+});
+
+test('moves up and clamps at the first row', () => {
+  expect(nextIndex(1, 3, 'ArrowUp')).toBe(0);
+  expect(nextIndex(0, 3, 'ArrowUp')).toBe(0);
+});
+
+test('Home and End jump to the edges', () => {
+  expect(nextIndex(1, 3, 'Home')).toBe(0);
+  expect(nextIndex(1, 3, 'End')).toBe(2);
+});
